import{i as e}from"./kit-KASxg-TP.js";var t=[`READ UNCOMMITTED`,`READ COMMITTED`,`REPEATABLE READ (snapshot)`,`SERIALIZABLE`],n={dirty:{name:`Dirty read`,steps:[`T1: UPDATE acct SET bal=0 WHERE id=1   (not committed)`,`T2: SELECT bal FROM acct WHERE id=1  -> sees 0?`,`T1: ROLLBACK`],allowed:[1,0,0,0],why:[`T2 reads uncommitted data that later disappears.`,`READ COMMITTED reads only committed versions.`,`Snapshot reads only committed versions as of start.`,`Serializable includes everything above.`]},nonrep:{name:`Non-repeatable read`,steps:[`T1: SELECT bal FROM acct WHERE id=1  -> 100`,`T2: UPDATE acct SET bal=50 WHERE id=1; COMMIT`,`T1: SELECT bal FROM acct WHERE id=1  -> 50?`],allowed:[1,1,0,0],why:[`Allowed.`,`Each statement takes a fresh snapshot, so T1 sees the new committed value.`,`T1 keeps its start-of-transaction snapshot (or holds read locks).`,`Prevented.`]},phantom:{name:`Phantom`,steps:[`T1: SELECT count(*) FROM orders WHERE day=5  -> 3`,`T2: INSERT INTO orders (day=5,...); COMMIT`,`T1: SELECT count(*) FROM orders WHERE day=5  -> 4?`],allowed:[1,1,0,0],why:[`Allowed.`,`Fresh snapshot per statement shows the new row.`,`PostgreSQL and MySQL(InnoDB gap/next-key locks) prevent phantoms at RR even though the SQL standard permits them.`,`Prevented (predicate/next-key locks or SSI).`]},lost:{name:`Lost update`,steps:[`T1: SELECT bal -> 100`,`T2: SELECT bal -> 100`,`T1: UPDATE SET bal=100+10; COMMIT`,`T2: UPDATE SET bal=100+20; COMMIT   (10 is lost?)`],allowed:[1,1,0,0],why:[`Allowed.`,`READ COMMITTED allows it for read-modify-write in app code (use SELECT FOR UPDATE or bal=bal+20).`,`First-committer-wins: T2 aborts with a serialization failure (PostgreSQL). MySQL RR lets it through for non-locking reads.`,`Prevented.`]},skew:{name:`Write skew (doctors on call)`,steps:[`Invariant: at least one doctor on call. Alice and Bob both on.`,`T1: SELECT count(*) WHERE on_call -> 2;  UPDATE SET on_call=false WHERE name=Alice`,`T2: SELECT count(*) WHERE on_call -> 2;  UPDATE SET on_call=false WHERE name=Bob`,`T1: COMMIT;  T2: COMMIT  -> nobody on call`],allowed:[1,1,1,0],why:[`Allowed.`,`Allowed: different rows are written, so no write-write conflict.`,`Snapshot isolation allows it: each txn saw a consistent snapshot, and they wrote disjoint rows.`,`Only true serializability (2PL range locks, SSI) detects the rw-dependency cycle and aborts one.`]}};function r(r){let i=e(`select`,{class:`dbtn`},Object.entries(n).map(([t,n])=>e(`option`,{value:t},n.name))),a=e(`select`,{class:`dbtn`},t.map((t,n)=>e(`option`,{value:n},t)));a.selectedIndex=1;let o=e(`div`,{class:`out`}),s=e(`div`,{class:`out`}),c=0;function l(){let e=n[i.value],r=+a.value,l=e.steps.length;if(o.innerHTML=e.steps.map((e,t)=>(t<c?`<span class="good">✓ </span>`:t===c?`<b>▶ </b>`:`  `)+e).join(`
`),c>=l){let n=e.allowed[r];s.innerHTML=`<b class="${n?`bad`:`good`}">${n?`ANOMALY OCCURS`:`ANOMALY PREVENTED`}</b> under ${t[r]}\n${e.why[r]}`}else s.textContent=`Step through the schedule...`}let u=(t,n)=>e(`button`,{class:`dbtn`,onclick:n},t);i.addEventListener(`change`,()=>{c=0,l()}),a.addEventListener(`change`,l),r.append(e(`div`,{class:`row`},e(`span`,{class:`dim`},`scenario`),i,e(`span`,{class:`dim`},`isolation`),a),o,e(`div`,{class:`row`},u(`Step ▶`,()=>{c<n[i.value].steps.length&&(c++,l())}),u(`Run all`,()=>{c=n[i.value].steps.length,l()}),u(`Reset`,()=>{c=0,l()})),s),l()}var i={n:12,title:`Isolation levels & anomalies`,minutes:16,cmu:`CMU 15-445 L16-L18, 15-721 L2`,components:[`isolation-levels`,`mvcc`,`lock-manager`],goals:[`Define dirty read, non-repeatable read, phantom, lost update, read skew and write skew.`,`Map the SQL standard levels onto what PostgreSQL, MySQL/InnoDB and others really do.`,`Pick an isolation level and know which invariants it silently leaves unprotected.`],body:`
<h2>Why levels exist</h2>
<p>Serializable execution is the gold standard but costs concurrency (locks) or aborts. SQL-92 defined weaker levels by the anomalies they allow. Berenson et al. (1995) showed the standard's definitions were ambiguous and missed important anomalies (snapshot isolation is not in the standard). Adya's formalism defines levels via dependency graphs.</p>
<h2>Anomalies</h2>
<table><tr><th>Anomaly</th><th>Meaning</th></tr>
<tr><td>Dirty read</td><td>read another txn's uncommitted write</td></tr>
<tr><td>Non-repeatable read</td><td>re-reading a row returns a different committed value</td></tr>
<tr><td>Phantom</td><td>re-running a predicate query returns different rows</td></tr>
<tr><td>Lost update</td><td>two read-modify-write cycles overwrite each other</td></tr>
<tr><td>Read skew</td><td>reading two related items at different times, seeing an inconsistent pair</td></tr>
<tr><td>Write skew</td><td>two txns read overlapping data and write disjoint items, violating an invariant</td></tr></table>
<div data-demo="0"></div>
<h2>What systems actually implement</h2>
<table><tr><th>System</th><th>Default</th><th>Notes</th></tr>
<tr><td>PostgreSQL</td><td>READ COMMITTED</td><td>REPEATABLE READ is snapshot isolation (no phantoms, but write skew possible, aborts on write conflict); SERIALIZABLE is SSI. READ UNCOMMITTED behaves as READ COMMITTED.</td></tr>
<tr><td>MySQL InnoDB</td><td>REPEATABLE READ</td><td>consistent snapshot for plain SELECT; locking reads and writes use next-key locks (record + gap) and see latest committed data, so plain and locking reads can disagree. SERIALIZABLE turns reads into shared locking reads.</td></tr>
<tr><td>Oracle</td><td>READ COMMITTED</td><td>"SERIALIZABLE" is actually snapshot isolation.</td></tr>
<tr><td>SQL Server</td><td>READ COMMITTED (locking); RCSI optional</td><td>SNAPSHOT isolation is opt-in; SERIALIZABLE uses key-range locks.</td></tr>
<tr><td>CockroachDB / Spanner</td><td>SERIALIZABLE / strict serializable</td><td>Timestamp ordering with restarts; Spanner adds external consistency via TrueTime.</td></tr>
<tr><td>TiDB / FoundationDB</td><td>snapshot (TiDB RR) / strict serializable (FDB)</td><td>FDB uses optimistic conflict detection on read ranges.</td></tr></table>
<div class="callout ripple"><div class="t">Isolation is implemented by lower layers</div><p>The level is just the visible effect of choices in concurrency control, MVCC and the lock manager: per-statement vs per-transaction snapshots, whether range/gap locks exist, and whether reads are tracked for dependency cycles.</p></div>
<h2>Practical guidance</h2>
<ul><li>Read-modify-write counters: use <code>UPDATE ... SET bal = bal + 20</code> or <code>SELECT ... FOR UPDATE</code>; do not read into the app and write back under RC.</li>
<li>Invariants over multiple rows (on-call, unique bookings, balances across accounts): use SERIALIZABLE and retry on serialization failure, or materialize the conflict (lock a parent row).</li>
<li>Long analytics: run at snapshot isolation on a replica to avoid holding back vacuum/purge.</li></ul>`,demos:[{title:`Anomaly lab`,caption:`Choose a scenario and an isolation level, step through the schedule, and see if the anomaly occurs (behaviour modelled on PostgreSQL and InnoDB).`,mount:r}],tradeoffs:{head:[`Level`,`Prevents`,`Cost`,`Typical mechanism`],rows:[[`READ UNCOMMITTED`,`nothing`,`cheapest`,`no read locks`],[`READ COMMITTED`,`dirty reads`,`low`,`statement-level snapshot or short read locks`],[`REPEATABLE READ / SI`,`non-repeatable, often phantoms`,`medium (version GC)`,`transaction snapshot`],[`SERIALIZABLE`,`all, including write skew`,`locks or aborts`,`2PL + range locks, SSI, OCC`],[`Strict serializable`,`+ real-time order`,`clock/consensus latency`,`TrueTime, TSO, Calvin`]]},ripples:[{to:`MVCC`,text:`statement vs transaction snapshots decide whether reads see new commits.`},{to:`Lock manager`,text:`phantom protection needs range/gap or predicate locks, which add lock-table pressure.`},{to:`Application`,text:`retry loops for serialization failures become part of correct application code.`},{to:`Replication`,text:`statement-based replication needs strong locking (gap locks) to be deterministic; row-based replication relaxes it.`}],quiz:[{q:`PostgreSQL REPEATABLE READ allows which anomaly?`,options:[`Dirty read`,`Write skew`,`Non-repeatable read`],answer:1,why:`It is snapshot isolation: no phantoms, but disjoint-row write skew is possible.`},{q:`Fix for lost update at READ COMMITTED?`,options:[`Nothing`,`Atomic UPDATE bal=bal+x or SELECT FOR UPDATE`,`Increase pool size`],answer:1,why:`Make the read-modify-write atomic or lock the row.`},{q:`Which level guarantees the doctors-on-call invariant?`,options:[`READ COMMITTED`,`Snapshot isolation`,`SERIALIZABLE`],answer:2,why:`Only true serializability prevents write skew.`}],refs:[{title:`Berenson et al., A Critique of ANSI SQL Isolation Levels`,url:`https://arxiv.org/abs/cs/0701157`},{title:`Ports & Grittner, Serializable Snapshot Isolation in PostgreSQL (VLDB 2012)`,url:`https://drkp.net/papers/ssi-vldb12.pdf`},{title:`PostgreSQL: Transaction Isolation`,url:`https://www.postgresql.org/docs/current/transaction-iso.html`},{title:`MySQL: InnoDB Transaction Isolation Levels`,url:`https://dev.mysql.com/doc/refman/8.0/en/innodb-transaction-isolation-levels.html`},{title:`Jepsen: Consistency models`,url:`https://jepsen.io/consistency`}]};export{i as default};